INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Entitätsbeziehungsmodell immer relational?', 2, '[{"text": "Ja", "correct": true, "because": "Basis für relationale Datenbanken"}, {"text": "Nein", "correct": false, "because": "Definiert durch Beziehungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für mich beim Entitätsbeziehungsmodell entscheidend?', 3, '[{"text": "Beziehungen zwischen Entitäten", "correct": true, "because": "Definiert Struktur"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}, {"text": "Minimale Speichergröße", "correct": false, "because": "Funktion wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Entitätsbeziehungsmodell?', 5, '[{"text": "Entitäten", "correct": true, "because": "Repräsentieren Objekte"}, {"text": "Beziehungen", "correct": true, "because": "Verbinden Entitäten"}, {"text": "Baumstruktur", "correct": false, "because": "Hierarchisches Modell"}, {"text": "Kapselung", "correct": false, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Entitäten und Beziehungen. b) Es ist baumartig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist hierarchisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Entitätsbeziehungsmodell?', 4, '[{"text": "Entitätsattribute", "correct": false, "because": "Beschreiben Entitäten"}, {"text": "Beziehungstypen", "correct": false, "because": "Definieren Verknüpfungen"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Modell auch schwache Entitäten hat?', 2, '[{"text": "Ja", "correct": true, "because": "Abhängig von starken Entitäten"}, {"text": "Nein", "correct": false, "because": "Teil des Modells"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Beziehung im Modell?', 3, '[{"text": "Raute", "correct": true, "because": "Standard für Beziehungen"}, {"text": "Kreis", "correct": false, "because": "Andere Bedeutung"}, {"text": "Dreieck", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir das Entitätsbeziehungsmodell?', 5, '[{"text": "Klare Struktur", "correct": true, "because": "Übersichtliche Darstellung"}, {"text": "Basis für Tabellen", "correct": true, "because": "Relational umsetzbar"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Struktur fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Es beschreibt Beziehungen. b) Es ist objektorientiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist anderes Modell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Entitätsbeziehungsmodell?', 4, '[{"text": "Entitäten", "correct": false, "because": "Grundbausteine"}, {"text": "Attribute", "correct": false, "because": "Beschreiben Entitäten"}, {"text": "Polymorphismus", "correct": true, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Modell für komplexe Hierarchien geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Besser für relationale Daten"}, {"text": "Ja", "correct": false, "because": "Hierarchisches Modell besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das Modell effektiv?', 4, '[{"text": "Klare Beziehungen", "correct": true, "because": "Strukturierte Verknüpfungen"}, {"text": "Eindeutige Schlüssel", "correct": true, "because": "Identifizieren Entitäten"}, {"text": "Baumstruktur", "correct": false, "because": "Anderes Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Modell nur für kleine Datenbanken ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar für alle Größen"}, {"text": "Ja", "correct": false, "because": "Größe nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Entitätsbeziehungsmodell?', 3, '[{"text": "Beziehungsdefinition", "correct": true, "because": "Kern des Modells"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Planung wichtiger"}, {"text": "Minimale Attribute", "correct": false, "because": "Beschreibung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Primärschlüssel. b) Es ist hierarchisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist anderes Modell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern das Entitätsbeziehungsmodell?', 5, '[{"text": "Kardinalitäten", "correct": true, "because": "Definieren Beziehungsarten"}, {"text": "Schlüsselattribute", "correct": true, "because": "Sichern Eindeutigkeit"}, {"text": "Viele-zu-viele-Hierarchien", "correct": false, "because": "Netzwerkmodell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Modell unwichtig?', 3, '[{"text": "Entitätsdefinition", "correct": false, "because": "Grundlage"}, {"text": "Beziehungsarten", "correct": false, "because": "Strukturieren Modell"}, {"text": "Design der Oberfläche", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt das Modell viele-zu-viele-Beziehungen direkt?', 3, '[{"text": "Nein", "correct": true, "because": "Braucht Zwischentabelle"}, {"text": "Ja", "correct": false, "because": "Indirekt über Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Modell für Planung geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Basis für Datenbankdesign"}, {"text": "Nein", "correct": false, "because": "Hauptzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung passt zum Entitätsbeziehungsmodell?', 4, '[{"text": "Datenbankdesign", "correct": true, "because": "Strukturierte Planung"}, {"text": "Dateisysteme", "correct": false, "because": "Hierarchisches Modell"}, {"text": "Programmlogik", "correct": false, "because": "Objektorientiert"}]');
